  const history = useRef<Message[]>([]); const turn = useRef(0); const thinking = useRef(false);
  const append = (message: Message) => { history.current = [...history.current, message]; setMessages(history.current); };
  const send = async (raw: string) => {
    const text = raw.trim();
    if (!text || thinking.current) return;
    const mine = ++turn.current;
    stopSpeaking(); setOpen(true); setDraft('');
    append({ role: 'user', text });
    const turns = history.current.filter(m => !m.error).map(({ role, text }) => ({ role, text })).slice(-14);
    thinking.current = true; setBusy(true);
    try {
      const result = await askAgent(turns, controller.current.context());
      thinking.current = false; setBusy(false);
      append({ role: 'assistant', text: result.reply, actions: result.actions });
      const act = async () => { for (const action of result.actions) { if (turn.current !== mine) return; await controller.current.run(action); } };
      // A narrated walkthrough speaks per step, so the intro line goes first; otherwise talk while acting.
      if (result.actions.some(action => action.type === 'play_steps')) { await speak(result.reply); await act(); }
      else await Promise.all([speak(result.reply), act()]);
    } catch (error) {
      append({ role: 'assistant', text: error instanceof Error ? error.message : 'Something went wrong. Please try again.', error: true });
    } finally { thinking.current = false; setBusy(false); }
  };
  const sendRef = useRef(send); sendRef.current = send;
  const talk = async () => {
    if (listening || busy) return;
    stopSpeaking(); setListening(true);
    try { const heard = await listen(); if (heard) await send(heard); }
    catch (error) { append({ role: 'assistant', text: error instanceof Error ? error.message : 'Voice input failed.', error: true }); }
    finally { setListening(false); }
  };
  useEffect(() => onNarration(text => append({ role: 'assistant', text, narration: true })), []);
  useEffect(() => onVoiceChange(() => setSilent(isMuted())), []);
  useEffect(() => { list.current?.scrollTo({ top: list.current.scrollHeight, behavior: 'smooth' }); }, [messages, busy, open]);
  useEffect(() => { if (open) input.current?.focus(); }, [open]);
  // Integration surface for the voice front end and for debugging from the console.
  useEffect(() => {
    const scope = window as unknown as { brickvision?: unknown };
    scope.brickvision = { send: (text: string) => sendRef.current(text), run: (action: ViewerAction) => controller.current.run(action),
      context: () => controller.current.context(), setVoice, speak, stop: stopSpeaking, open: () => setOpen(true) };
    return () => { delete scope.brickvision; };
  }, [controller]);
  const submit = (event: FormEvent) => { event.preventDefault(); void send(draft); };
  return <div className={`buddy${open ? ' open' : ''}`}>
    {open && <section className="buddy-panel" aria-label="Build buddy chat">
      <header className="buddy-header">
        <span className="buddy-avatar" aria-hidden="true"><IconSparkles size={20}/></span>
        <div className="buddy-title"><strong>BrickBuddy</strong><small role="status">{busy ? 'Thinking…' : listening ? 'Listening…' : 'Ask me to move, explain or spin the model'}</small></div>
        <button type="button" className="buddy-icon" aria-pressed={!silent} aria-label={silent ? 'Turn voice on' : 'Turn voice off'} title={silent ? 'Turn voice on' : 'Turn voice off'} onClick={() => setMuted(!silent)}>{silent ? <IconVolumeOff size={19}/> : <IconVolume size={19}/>}</button>
        <button type="button" className="buddy-icon" aria-label="Close chat" title="Close chat" onClick={() => setOpen(false)}><IconX size={19}/></button>
      </header>
      <div className="buddy-messages" ref={list} aria-live="polite">
        {messages.length === 0 && <div className="buddy-empty"><p>Hi! I can drive the 3D model while your hands are busy. Try:</p>{SUGGESTIONS.map(text => <button type="button" key={text} onClick={() => void send(text)}>{text}</button>)}</div>}
        {messages.map((message, i) => <div key={i} className={`buddy-msg ${message.role}${message.error ? ' error' : ''}${message.narration ? ' narration' : ''}`}>
          <p>{message.text}</p>
          {message.actions && message.actions.length > 0 && <div className="buddy-chips">{message.actions.map((action, k) => <span key={k}>{describeAction(action)}</span>)}</div>}
        </div>)}
        {busy && <div className="buddy-msg assistant typing" aria-label="BrickBuddy is thinking"><span/><span/><span/></div>}
      </div>
      <form className="buddy-form" onSubmit={submit}>
        <button type="button" className={`buddy-mic${listening ? ' live' : ''}`} aria-label={listening ? 'Listening' : 'Talk to BrickBuddy'} title="Talk to BrickBuddy" disabled={busy} onClick={() => void talk()}><IconMicrophone size={20}/></button>
        <input ref={input} value={draft} onChange={event => setDraft(event.target.value)} placeholder="Ask BrickBuddy…" aria-label="Message BrickBuddy" autoComplete="off"/>
        <button type="submit" className="buddy-send" aria-label="Send" disabled={busy || !draft.trim()}><IconSend2 size={19}/></button>
      </form>
    </section>}
    <button type="button" className="buddy-launcher" aria-expanded={open} aria-label={open ? 'Hide build buddy' : 'Chat with your build buddy'} title="BrickBuddy" onClick={() => setOpen(value => !value)}>{open ? <IconX size={26}/> : <IconMessageChatbot size={28}/>}</button>
  </div>;
}

input.content:
/* BrickBuddy: floating chat that drives the 3D viewer. Sits bottom-right of the model pane. */
.buddy{position:absolute;right:36px;bottom:20px;z-index:3;display:flex;align-items:flex-end;gap:14px;pointer-events:none}
.buddy>*{pointer-events:auto}
.buddy .buddy-launcher{width:56px;height:56px;padding:0;border-radius:50%;background:var(--yellow);border:2px solid #142d4c;color:#142d4c;box-shadow:0 4px 0 #142d4c,0 14px 30px #14305233;transition:transform .15s,box-shadow .15s}
.buddy .buddy-launcher:hover:not(:disabled){background:#ffd60a;border-color:#142d4c;transform:translateY(-2px);box-shadow:0 6px 0 #142d4c,0 18px 34px #14305240}
.buddy .buddy-launcher:active{transform:translateY(3px);box-shadow:0 1px 0 #142d4c}
.buddy.open .buddy-launcher{background:#fff}
.buddy-panel{width:360px;height:540px;max-height:calc(100dvh - 238px);display:flex;flex-direction:column;background:#fff;border:2px solid #142d4c;border-radius:18px;box-shadow:0 6px 0 #142d4c,0 24px 60px #1430523d;overflow:hidden;animation:buddy-in .22s cubic-bezier(.2,.9,.3,1.2)}
@keyframes buddy-in{from{opacity:0;transform:translateY(14px) scale(.96)}to{opacity:1;transform:none}}
.buddy-header{display:flex;align-items:center;gap:10px;padding:12px 12px 12px 14px;background:var(--yellow);border-bottom:2px solid #142d4c}
.buddy-avatar{width:36px;height:36px;border-radius:10px;background:#142d4c;color:var(--yellow);display:grid;place-items:center;flex:none}
.buddy-title{flex:1;min-width:0;display:flex;flex-direction:column;line-height:1.25}
.buddy-title strong{font-size:15px;letter-spacing:-.01em}
.buddy-title small{font-size:11.5px;color:#4a4410;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.buddy .buddy-icon{width:34px;height:34px;padding:0;border-radius:9px;background:transparent;border-color:transparent;color:#142d4c}
.buddy .buddy-icon:hover:not(:disabled){background:#142d4c1a;border-color:transparent}
.buddy .buddy-icon[aria-pressed=true]{background:#142d4c;color:var(--yellow)}
.buddy-messages{flex:1;min-height:0;overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:9px;background:#f6f8fb;scrollbar-width:thin}
.buddy-empty{margin:auto 0;display:flex;flex-direction:column;gap:8px;align-items:flex-start}
.buddy-empty p{margin:0 0 4px;font-size:14px;line-height:1.5;color:#3d5169}
.buddy .buddy-empty button{padding:8px 13px;border-radius:999px;background:#fff;border:1.5px solid #c9d6e6;color:#17426a;font-size:13px;font-weight:600}
.buddy .buddy-empty button:hover:not(:disabled){background:var(--yellow-soft);border-color:#142d4c}
.buddy-msg{max-width:86%;padding:9px 13px;border-radius:16px;font-size:14px;animation:buddy-in .18s ease-out}
.buddy-msg p{margin:0;line-height:1.45;overflow-wrap:anywhere}
.buddy-msg.user{align-self:flex-end;background:var(--blue);color:#fff;border-bottom-right-radius:5px}
.buddy-msg.assistant{align-self:flex-start;background:#fff;border:1px solid #dfe7f0;border-bottom-left-radius:5px}
.buddy-msg.narration{background:var(--yellow-soft);border-color:#e6d26a;border-left:4px solid var(--yellow)}
.buddy-msg.error{background:#fff1f0;border-color:#f3c2be;color:#8f2219}
.buddy-chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:7px}
.buddy-chips span{font-size:11.5px;font-weight:650;padding:3px 9px;border-radius:999px;background:#eaf1ff;color:#1b55b8;border:1px solid #c9dafb;white-space:nowrap}
.buddy-msg.typing{display:flex;gap:5px;padding:13px 15px}
.buddy-msg.typing span{width:7px;height:7px;border-radius:50%;background:#8da0b8;animation:buddy-dot 1s infinite ease-in-out}
.buddy-msg.typing span:nth-child(2){animation-delay:.15s}.buddy-msg.typing span:nth-child(3){animation-delay:.3s}
@keyframes buddy-dot{0%,60%,100%{transform:none;opacity:.5}30%{transform:translateY(-5px);opacity:1}}
.buddy-form{display:flex;align-items:center;gap:8px;padding:10px;border-top:1px solid #e3e9f0;background:#fff}
.buddy .buddy-form input{flex:1;min-width:0;height:42px;padding:0 14px;font-size:14px;border:1.5px solid #c9d6e6;border-radius:999px;background:#f6f8fb;color:var(--ink)}
.buddy .buddy-form input:focus-visible{outline:none;border-color:var(--blue);background:#fff}
.buddy .buddy-mic,.buddy .buddy-send{width:42px;height:42px;padding:0;border-radius:50%;flex:none}
.buddy .buddy-mic{background:#fff;border:1.5px solid #142d4c;color:#142d4c}
.buddy .buddy-mic:hover:not(:disabled){background:var(--yellow);border-color:#142d4c}
.buddy .buddy-mic.live{background:#e5383b;border-color:#e5383b;color:#fff;animation:buddy-pulse 1.1s infinite}
@keyframes buddy-pulse{0%{box-shadow:0 0 0 0 #e5383b80}100%{box-shadow:0 0 0 12px #e5383b00}}
@media(max-width:1000px){.buddy{right:12px;bottom:12px;flex-direction:column;gap:10px}.buddy-panel{width:min(360px,calc(100vw - 24px));max-height:calc(100dvh - 300px)}}
@media(prefers-reduced-motion:reduce){.buddy-panel,.buddy-msg,.buddy-msg.typing span,.buddy .buddy-mic.live{animation:none}}

